  <style>
    :root {
      --alhazen-primary: #059669;
      --alhazen-primary-dark: #047857;
      --alhazen-secondary: #facc15;
      --alhazen-accent: #f97316;
      --alhazen-background: #f9fafb;
      --alhazen-text: #0f172a;
      --alhazen-neutral: #e5e7eb;
      --toolbar-height: 52px;
    }
    body {
      color: var(--alhazen-text);
      font-family: 'Poppins', ui-sans-serif, system-ui, sans-serif;
      overflow: hidden;
      margin: 0;
      padding: 0;
    }
    :root, body.is-fullscreen {
      background-color: var(--alhazen-background);
    }
    [hidden] {
      display: none !important;
    }
    h1 {
      font-weight: normal;
    }
    a {
      color: inherit;
      text-decoration: underline;
      cursor: pointer;
    }

    #app, #loading, #error, #launch {
      position: absolute;
      top: var(--toolbar-height);
      left: 0;
      width: 100%;
      height: calc(100% - var(--toolbar-height));
    }
    body.is-fullscreen #app,
    body.is-fullscreen #loading,
    body.is-fullscreen #error,
    body.is-fullscreen #launch {
      top: 0;
      height: 100%;
    }
    .screen {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      text-align: center;
      cursor: default;
      user-select: none;
      -webkit-user-select: none;
      background-color: #ffffff;
    }
    #launch {
      background-color: rgba(0, 0, 0, 0.7);
      cursor: pointer;
    }
    .green-flag {
      width: 80px;
      height: 80px;
      padding: 16px;
      border-radius: 100%;
      background: rgba(255, 255, 255, 0.75);
      border: 3px solid hsla(0, 100%, 100%, 1);
      display: flex;
      justify-content: center;
      align-items: center;
      box-sizing: border-box;
    }
    #loading {
      background-image: url(data:image/png;base64,);
      background-repeat: no-repeat;
      background-size: contain;
      background-position: center;
    }
    .progress-bar-outer {
      border: 1px solid currentColor;
      height: 10px;
      width: 200px;
      max-width: 200px;
    }
    .progress-bar-inner {
      height: 100%;
      width: 0;
      background-color: currentColor;
    }
    .loading-text, noscript {
      font-weight: normal;
      font-size: 36px;
      margin: 0 0 16px;
    }
    .loading-image {
      margin: 0 0 16px;
    }
    #error-message, #error-stack {
      font-family: monospace;
      max-width: 600px;
      white-space: pre-wrap;
      user-select: text;
      -webkit-user-select: text;
    }
    #error-stack {
      text-align: left;
      max-height: 200px;
      overflow: auto;
    }
    .control-button {
      width: 2rem;
      height: 2rem;
      padding: 0.375rem;
      margin-top: 0.5rem;
      margin-bottom: 0.5rem;
      user-select: none;
      -webkit-user-select: none;
      cursor: pointer;
      border: 0;
      border-radius: 4px;
    }
    .control-button-highlight:hover {
      background: #ff4c4c26;
    }
    .control-button-highlight.active {
      background: #ff4c4c59;
    }
    .fullscreen-button {
      background: white;
    }
    .standalone-fullscreen-button {
      position: absolute;
      top: 0;
      right: 0;
      background-color: rgba(0, 0, 0, 0.5);
      border-radius: 0 0 0 4px;
      padding: 4px;
      cursor: pointer;
    }
    .sc-canvas {
      cursor: auto;
    }
    .sc-monitor-root[data-opcode^="data_"] .sc-monitor-value-color {
      background-color: #ff8c1a;
    }
    .sc-monitor-row-value-outer {
      background-color: #fc662c;
    }
    .sc-monitor-row-value-editing .sc-monitor-row-value-outer {
      background-color: #e25b27;
    }

    .preview-toolbar {
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: var(--toolbar-height);
      z-index: 9000;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 0 12px;
      box-sizing: border-box;
      background-color: var(--alhazen-primary);
      color: #ffffff;
      font-family: 'Poppins', ui-sans-serif, system-ui, sans-serif;
    }
    body.is-fullscreen .preview-toolbar {
      display: none;
    }
    .preview-toolbar__judul {
      font-family: 'Fredoka', 'Poppins', sans-serif;
      font-size: 15px;
      font-weight: 600;
      letter-spacing: 0.02em;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .preview-toolbar__aksi {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-shrink: 0;
    }
    .preview-toolbar button {
      border: 0;
      border-radius: 999px;
      padding: 7px 14px;
      background-color: var(--alhazen-secondary);
      color: var(--alhazen-text);
      font-family: inherit;
      font-size: 13px;
      font-weight: 600;
      cursor: pointer;
      transition: background-color 0.15s ease;
    }
    .preview-toolbar button:hover {
      background-color: #fde047;
    }
    .preview-toolbar button:focus-visible {
      outline: 2px solid #ffffff;
      outline-offset: 2px;
    }

    #petunjuk {
      position: absolute;
      inset: 0;
      z-index: 9999;
      display: flex;
      align-items: center;
      justify-content: center;
      background: rgba(15, 23, 42, 0.72);
      color: var(--alhazen-text);
      font-family: 'Poppins', ui-sans-serif, system-ui, sans-serif;
      padding: 20px;
      box-sizing: border-box;
    }
    #petunjuk .kotak {
      max-width: 620px;
      max-height: 90%;
      overflow: auto;
      background: #ffffff;
      color: var(--alhazen-text);
      padding: 28px;
      border-radius: 20px;
      border-top: 6px solid var(--alhazen-accent);
      box-shadow: 0 20px 50px rgba(15, 23, 42, 0.35);
      line-height: 1.6;
      text-align: left;
    }
    #petunjuk h2 {
      margin-top: 0;
      font-family: 'Fredoka', 'Poppins', sans-serif;
      font-size: 26px;
      color: var(--alhazen-primary);
    }
    #petunjuk ul {
      padding-left: 20px;
      margin: 8px 0;
    }
    #petunjuk li {
      margin-bottom: 6px;
    }
    #petunjuk button {
      margin-top: 16px;
      padding: 12px 28px;
      font-size: 16px;
      font-family: inherit;
      font-weight: 600;
      border: 0;
      border-radius: 999px;
      background-color: var(--alhazen-primary);
      color: #ffffff;
      cursor: pointer;
      transition: background-color 0.15s ease;
    }
    #petunjuk button:hover {
      background-color: var(--alhazen-primary-dark);
    }

  </style>
  <link rel="icon" href="data:image/png;base64,">
</head>
<body>
  <header class="preview-toolbar">
    <span class="preview-toolbar__judul">Lari ke Sekolah</span>
    <div class="preview-toolbar__aksi">
      <button type="button" id="btn-petunjuk">Petunjuk</button>
      <button type="button" id="btn-muat-ulang">Muat Ulang</button>
      <button type="button" id="btn-layar-penuh">Layar Penuh</button>
    </div>
  </header>
  <div id="petunjuk">
    <div class="kotak">
      <h2>UMAR LARI KE SEKOLAH</h2>
      <p><strong>Bantu Umar sampai ke SD Alhazen sebelum energinya habis!</strong></p>

      <p><strong>CARA MAIN:</strong></p>
      <ul>
        <li>Tekan tombol <strong>PANAH ATAS</strong> untuk melompat.</li>
        <li>Hindari kayu yang melintang di jalan.</li>
        <li>Tekan tombol <strong>PANAH BAWAH</strong> untuk sliding.</li>
        <li>Hindari ayam yang terbang kesana-kemari.</li>
        <li>Energi Umar akan berkurang sendiri seiring waktu, jadi jangan buang-buang waktu.</li>
        <li>Kalau kena rintangan, energi berkurang lebih banyak, hati-hati.</li>
      </ul>

      <p><strong>TUJUAN:</strong></p>
      <p>Sampai ke gerbang sekolah sebelum energi Umar habis. Kalau energi habis duluan sebelum sampai, Umar keburu lelah.</p>

      <p>Selamat mencoba, semoga Umar gak telat sekolah.</p>

      <button type="button" id="tutup-petunjuk">
        Mulai
      </button>
    </div>
  </div>

  <script>
    (function () {
      var modal = document.getElementById('petunjuk');
      var mulai = document.getElementById('tutup-petunjuk');
      var bantuan = document.getElementById('btn-petunjuk');
      var muatUlang = document.getElementById('btn-muat-ulang');
      var layarPenuh = document.getElementById('btn-layar-penuh');

      if (mulai) {
        mulai.addEventListener('click', function () {
          modal.style.display = 'none';
        });
      }
      if (bantuan) {
        bantuan.addEventListener('click', function () {
          modal.style.display = 'flex';
        });
      }
      if (muatUlang) {
        muatUlang.addEventListener('click', function () {
          window.location.reload();
        });
      }
      if (layarPenuh) {
        layarPenuh.addEventListener('click', function () {
          if (document.fullscreenElement) {
            document.exitFullscreen();
          } else if (document.documentElement.requestFullscreen) {
            document.documentElement.requestFullscreen();
          }
        });
        document.addEventListener('fullscreenchange', function () {
          layarPenuh.textContent = document.fullscreenElement ? 'Keluar Layar Penuh' : 'Layar Penuh';
        });
      }
    })();
  </script>
  <div id="app"></div>

  <div id="launch" class="screen" hidden title="Click to start">
    <div class="green-flag">
      <svg viewBox="0 0 16.63 17.5" width="42" height="44">
        <defs><style>.cls-1,.cls-2{fill:#4cbf56;stroke:#45993d;stroke-linecap:round;stroke-linejoin:round;}.cls-2{stroke-width:1.5px;}</style></defs>
        <path class="cls-1" d="M.75,2A6.44,6.44,0,0,1,8.44,2h0a6.44,6.44,0,0,0,7.69,0V12.4a6.44,6.44,0,0,1-7.69,0h0a6.44,6.44,0,0,0-7.69,0"/>
        <line class="cls-2" x1="0.75" y1="16.75" x2="0.75" y2="0.75"/>
      </svg>
    </div>
  </div>

  <div id="loading" class="screen">
    <noscript>Enable JavaScript</noscript>


    <div class="progress-bar-outer"><div class="progress-bar-inner" id="loading-inner"></div></div>
  </div>

  <div id="error" class="screen" hidden>
    <h1>Error</h1>
    <details>
      <summary id="error-message"></summary>
      <p id="error-stack"></p>
    </details>
  </div>

